Lemma tail_word_bytes (s0r : word) (L W W' : Z) :
  0 <= W < 2^64 -> 0 <= W' < 2^64 -> 0 <= L < 65536 ->
  bv_unsigned s0r mod 65536 = L -> W' mod 65536 = L -> Z.shiftr W' 16 = Z.shiftr W 16 ->
